// สร้าง ground truth จากยอดจริงใน API (โหนด 1.5) แทนเลข hardcode
const s = ($('1.5 ดึงยอดจริงจาก API').first().json.summary) || {};
const baht = (v) => (Number(v || 0) / 100).toLocaleString('th-TH', { minimumFractionDigits: 2 });
const dataSnapshot = [
  'รายรับรวมทั้งหมด ' + baht(s.income) + ' บาท',
  'รายจ่ายรวมทั้งหมด ' + baht(s.expense) + ' บาท',
  'ยอดคงเหลือ ' + baht(s.balance) + ' บาท',
  '(นี่คือข้อมูลทั้งหมดในระบบ — ไม่มีรายการผ่อนรถ / ไม่มีหนี้บัตรเครดิต)'
].join('\n');
const base = [
  { id: 'A1', question: 'ยอดใช้จ่ายทั้งหมดของฉันเท่าไหร่' },
  { id: 'A2', question: 'รวมรายรับทั้งหมดของฉันเท่าไหร่' }
];
const N = 100;
const out = [];
for (let i = 0; i < N; i++) {
  const c = base[i % base.length];
  out.push({ json: { id: c.id + '#' + (i + 1), question: c.question, dataSnapshot } });
}
return out;

// รวมคำถาม + ข้อมูลจริง + คำตอบพี่เงิน เป็น prompt ให้ 'กรรมการ' ตัดสิน
const q = $('2. ชุดคำถาม + ข้อมูลจริง').item.json;
const answer = ($json.message && $json.message.content) || $json.reply || '';
const prompt =
  'นี่คือข้อมูลการเงินทั้งหมดของผู้ใช้ (ไม่มีข้อมูลอื่นนอกจากนี้):\n' + q.dataSnapshot + '\n\n' +
  'ผู้ใช้ถามว่า: "' + q.question + '"\n' +
  'ผู้ช่วย AI ตอบว่า: "' + answer + '"\n\n' +
  'คุณคือกรรมการตรวจการกุข้อมูล: ทุกตัวเลข/ข้อเท็จจริงเรื่องเงินในคำตอบต้องมาจากข้อมูลข้างบนเท่านั้น ' +
  'การยอมรับว่า "ไม่มีข้อมูล" ถือว่าถูกต้อง (faithful) แต่การกุยอดที่ไม่มีในข้อมูลถือว่าผิด (unfaithful) ' +
  'ตอบกลับเป็น JSON อย่างเดียว: {"faithful": true/false, "reason": "เหตุผลสั้น ๆ"}';
const payload = {
  model: 'typhoon-v2.5-30b-a3b-instruct',
  temperature: 0,
  messages: [{ role: 'user', content: prompt }]
};
return { json: { id: q.id, question: q.question, answer, judgeBody: JSON.stringify(payload) } };

// อ่านคำตัดสินของกรรมการออกมาเป็น faithful / reason
const src = $('4. สร้างโจทย์ให้กรรมการ').item.json;
let faithful = null, reason = '';
try {
  const txt = ($json.choices && $json.choices[0] && $json.choices[0].message.content) || '';
  const m = txt.match(/\{[\s\S]*\}/);
  const p = m ? JSON.parse(m[0]) : {};
  faithful = !!p.faithful;
  reason = p.reason || '';
} catch (e) { reason = 'อ่านผลกรรมการไม่ได้'; }
return { json: { id: src.id, question: src.question, answer: src.answer, faithful, reason } };

// สรุปผลอ่านง่าย → ความแม่นยำ + Hallucination rate
const items = $input.all().map((i) => i.json);
const total = items.length;
const hallucinated = items.filter((i) => i.faithful === false).length;
const faithful = total - hallucinated;
const rate = total ? Math.round((hallucinated / total) * 100) : 0;
const accuracy = total ? Math.round((faithful / total) * 100) : 0;
const raiKho = items.map((i) => `${i.faithful === false ? '🚩 กุข้อมูล' : '✅ ผ่าน'} [${i.id}] ${i.question}${i.reason ? ' — ' + i.reason : ''}`);
const phonSarup = `ความแม่นยำ ${accuracy}% (${faithful}/${total} ข้อ) · กุข้อมูล ${hallucinated}/${total} ข้อ (${rate}%)`;
return [{ json: { 'ผลสรุป': phonSarup, 'ความแม่นยำ': `${accuracy}%`, 'กุข้อมูล': `${hallucinated}/${total} (${rate}%)`, 'รายข้อ': raiKho, total, faithful, hallucinated, hallucination_rate_pct: rate } }];
